package org.apache.commons.lang.text;

import junit.framework.TestCase;

public class AgentBRT_Lang_61_raw_diff_Test extends TestCase {

    public void testReproduceBug() {
        StrBuilder strBuilder = new StrBuilder(10);
        strBuilder.append("hello world");

        // The buffer is larger than the content size, and we search for "world"
        // which starts at index 6. The pre-fix version will incorrectly calculate
        // the loop boundary and fail to find "world".
        int index = strBuilder.indexOf("world");

        // We expect to find "world" starting at index 6
        assertEquals(6, index);
    }
}

